"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFooterContent } from "./components/footer-sections/content";
import View4 from "./components/footer-sections/variants/05-local-time";
const variants = {"local-time":View4};
export type { ArtemisFooterClock, ArtemisFooterColumn, ArtemisFooterColumnLink, ArtemisFooterContent, ArtemisFooterImage, ArtemisFooterLink, ArtemisFooterNewsletter, ArtemisFooterSocialLink } from "./components/footer-sections/content";
export interface ArtemisFooterSectionsProps { className?: string; variant?: "local-time"; /** The words on the footer; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFooterContent>; }
export function ArtemisFooterSections({ className, variant = "local-time", content }: ArtemisFooterSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link, and where it goes. Links to other sites (http or https) open in a new tab. */
export interface ArtemisFooterLink {
  label: string;
  href: string;
}

/** A link in a column. */
export interface ArtemisFooterColumnLink extends ArtemisFooterLink {
  /** Shows the link in the stronger style, for a "browse all" link. landscape. */
  highlight?: boolean;
}

/** A small heading over a list of links. */
export interface ArtemisFooterColumn {
  title: string;
  links: ArtemisFooterColumnLink[];
}

/** A profile or contact link drawn as an icon. Its label names the link for screen readers, and is its tooltip where the layout has one. */
export interface ArtemisFooterSocialLink extends ArtemisFooterLink {
  /** The icon. Without one, the link keeps the icon the layout draws in that position. */
  icon?: ComponentType<{ className?: string }>;
}

/** A picture, and the words that describe it. */
export interface ArtemisFooterImage {
  src: string;
  alt: string;
}

/** An email sign-up form. */
export interface ArtemisFooterNewsletter {
  /** The heading over the form. */
  title: string;
  /** A line under the heading. */
  text: string;
  /** Sample text in the empty email field. */
  placeholder: string;
  /** The button. */
  button: string;
  /** The button while the address is being sent. */
  sending: string;
  /** The button once the address is sent. */
  sent: string;
}

/** A live clock for one city. */
export interface ArtemisFooterClock {
  /** The city named beside the clock face. */
  city: string;
  /** The city's IANA time zone, such as "Europe/Copenhagen". The clock stays blank if the zone is unknown. */
  timeZone: string;
  /** A line over the time. */
  caption: string;
}

/** The words on an Artemis footer. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFooterContent {
  /** The name beside the logo mark, and where it links. All layouts; wordmark, spotlight and mega show the name without a link, and wordmark and spotlight also draw it large across the foot. */
  brand: ArtemisFooterLink;
  /** A sentence about the brand. landscape, studio, local-time, frame, spotlight, mega and cta. */
  tagline?: string;
  /** The footer's main line. panorama and wordmark show it as a heading, landscape as a line under `tagline`, studio as a line over `cta`. */
  headline?: string;
  /** The styled end of the headline. It goes with `headline`: give `headline` alone and it shows alone, give both and both show. panorama, wordmark and landscape style it; studio runs it on after `headline`. */
  headlineAccent?: string;
  /** A paragraph under the headline. panorama. */
  subhead?: string;
  /** The main link. panorama and wordmark show it as a button, studio as a large underlined link. */
  cta?: ArtemisFooterLink;
  /** A quieter button beside `cta`. panorama. */
  secondaryCta?: ArtemisFooterLink;
  /** A short status, such as availability. studio and mega show it in a pill with a dot. */
  status?: string;
  /** A picture. panorama shows it wide; studio shows it over `location`. */
  image?: ArtemisFooterImage;
  /** Where you are, beside a map pin. studio. */
  location?: string;
  /** A row of links without headings. panorama and studio, which list the links of `columns` instead when you give only those. */
  links?: ArtemisFooterLink[];
  /** Columns of links under small headings. wordmark, landscape, local-time, frame, spotlight, mega and cta. */
  columns?: ArtemisFooterColumn[];
  /** An email sign-up form. mega. */
  newsletter?: ArtemisFooterNewsletter;
  /** A live clock for one city. local-time. */
  clock?: ArtemisFooterClock;
  /** Icon links to profiles or email. panorama, landscape, studio, frame, mega and cta. */
  social?: ArtemisFooterSocialLink[];
  /** The copyright line. All layouts but landscape. */
  legal?: string;
  /** Small links beside the copyright line. panorama, studio, local-time, frame and cta. */
  legalLinks?: ArtemisFooterLink[];
  /** A short closing line near the copyright. wordmark, frame and spotlight. */
  note?: string;
}

"use client";
// @zeus-internal
import { MotionConfig, motion } from "motion/react";
import { useEffect, useState } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisFooterContent } from "../content";
const REVEAL = { duration: 0.45, ease: ARTEMIS_EASE_OUT };
const DEFAULT = {
    brand: { label: "Workspace", href: "/" },
    tagline: "Independent minds, shared direction. We build thoughtful digital experiences for everyday life.",
    columns: [
        { title: "Explore", links: [{ label: "Selected work", href: "/work" }, { label: "Our approach", href: "/about" }, { label: "Notes", href: "/journal" }] },
        { title: "Connect", links: [{ label: "Email us", href: "mailto:hello@example.com" }, { label: "Instagram", href: "https://instagram.com" }, { label: "LinkedIn", href: "https://linkedin.com" }] },
    ],
    clock: { city: "Copenhagen", timeZone: "Europe/Copenhagen", caption: "A moment in our corner of the world" },
    legal: "\u00A9 2026 Workspace. Made with intention.",
    legalLinks: [{ label: "Privacy", href: "/privacy" }, { label: "Terms", href: "/terms" }],
} satisfies ArtemisFooterContent;
type ClockParts = {
    hours: string;
    minutes: string;
    seconds: string;
    date: string;
    hourAngle: number;
    minuteAngle: number;
    iso: string;
};
type ClockFormats = { time: Intl.DateTimeFormat; date: Intl.DateTimeFormat };
/** The formats for one time zone, or null when the zone is unknown. */
function clockFormats(timeZone: string): ClockFormats | null {
    try {
        return {
            time: new Intl.DateTimeFormat("en-GB", { timeZone, hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" }),
            date: new Intl.DateTimeFormat("en-GB", { timeZone, weekday: "short", day: "numeric", month: "short" }),
        };
    }
    catch {
        return null;
    }
}
function readClock(now: Date, formats: ClockFormats): ClockParts {
    const time = Object.fromEntries(formats.time.formatToParts(now).map((part) => [part.type, part.value]));
    const date = Object.fromEntries(formats.date.formatToParts(now).map((part) => [part.type, part.value]));
    const h = Number(time.hour ?? "0");
    const m = Number(time.minute ?? "0");
    return {
        hours: time.hour ?? "--",
        minutes: time.minute ?? "--",
        seconds: time.second ?? "--",
        date: `${date.weekday ?? ""} ${date.day ?? ""} ${date.month ?? ""}`,
        hourAngle: (h % 12) * 30 + m * 0.5,
        minuteAngle: m * 6,
        iso: now.toISOString(),
    };
}
function useLocalClock(timeZone: string): ClockParts | null {
    const [clock, setClock] = useState<ClockParts | null>(null);
    useEffect(() => {
        const formats = clockFormats(timeZone);
        if (!formats) {
            setClock(null);
            return;
        }
        setClock(readClock(new Date(), formats));
        const id = window.setInterval(() => setClock(readClock(new Date(), formats)), 1000);
        return () => window.clearInterval(id);
    }, [timeZone]);
    return clock;
}
/** Links to other sites open in a new tab, and carry an arrow in the columns. */
const isExternal = (href: string) => /^https?:/.test(href);
const newTab = (href: string) => (isExternal(href) ? { target: "_blank", rel: "noreferrer noopener" } : {});
export default function FooterSectionsLocalTime({ content }: { content?: Partial<ArtemisFooterContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const clock = useLocalClock(copy.clock.timeZone);
    return (<>
      <footer className="art:w-full art:bg-background art:px-6 art:py-8 art:text-foreground art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:py-12">
        <div className="art:mx-auto art:max-w-6xl">
          <MotionConfig reducedMotion="user">
          <motion.div className="art:grid art:gap-10 art:pb-10 art:@min-[768px]/artemis:grid-cols-2 art:@min-[768px]/artemis:gap-20" initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={REVEAL}>
            <div>
              <a href={copy.brand.href} {...newTab(copy.brand.href)} className="art:inline-flex art:min-h-10 art:items-center art:gap-3 art:rounded-full art:text-xl art:font-medium art:tracking-tight art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring">
                <span aria-hidden="true">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-compass art:size-6" aria-hidden="true">
                    <circle cx="12" cy="12" r="10"/>
                    <path d="m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z"/>
                  </svg>
                </span>
                {copy.brand.label}
              </a>
              <p className="art:mt-4 art:max-w-sm art:text-sm art:leading-6 art:text-muted-foreground">
                {copy.tagline}
              </p>
            </div>
            <div className="art:grid art:grid-cols-2 art:gap-8">
              {copy.columns.map((column, index) => <nav key={index} aria-label={column.title}>
                <h2 className="art:mb-3 art:text-xs art:font-medium art:text-muted-foreground">
                  {column.title}
                </h2>
                <ul>
                  {column.links.map((link, linkIndex) => <li key={linkIndex}>
                    <a href={link.href} {...newTab(link.href)} className="art:inline-flex art:min-h-10 art:items-center art:gap-1.5 art:rounded-full art:text-muted-foreground art:transition-colors art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:text-sm">
                      {link.label}
                      {isExternal(link.href) ? (
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3.5" aria-hidden="true">
                        <path d="M7 7h10v10"/>
                        <path d="M7 17 17 7"/>
                      </svg>
                      ) : null}
                    </a>
                  </li>)}
                </ul>
              </nav>)}
            </div>
          </motion.div>
          </MotionConfig>
          <div className="art:flex art:flex-col art:gap-6 art:border-y art:border-border art:py-7 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-center art:@min-[640px]/artemis:justify-between art:@min-[640px]/artemis:py-9">
            <div className="art:flex art:items-center art:gap-4">
              <svg aria-hidden="true" viewBox="0 0 64 64" className="art:size-14 art:shrink-0 art:text-foreground">
                <circle cx="32" cy="32" r="29" fill="none" stroke="currentColor" strokeOpacity="0.15"/>
                <path d="M32 7v4" stroke="currentColor" strokeOpacity="0.4" transform="rotate(0 32 32)"/>
                <path d="M32 7v4" stroke="currentColor" strokeOpacity="0.4" transform="rotate(90 32 32)"/>
                <path d="M32 7v4" stroke="currentColor" strokeOpacity="0.4" transform="rotate(180 32 32)"/>
                <path d="M32 7v4" stroke="currentColor" strokeOpacity="0.4" transform="rotate(270 32 32)"/>
                <path d="M32 32V18" stroke="currentColor" strokeWidth="2" strokeLinecap="round" transform={`rotate(${clock ? clock.hourAngle : 0} 32 32)`}/>
                <path d="M32 32V12" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" transform={`rotate(${clock ? clock.minuteAngle : 0} 32 32)`}/>
                <circle cx="32" cy="32" r="2" fill="currentColor"/>
              </svg>
              <div>
                <p className="art:text-sm art:font-medium">
                  {copy.clock.city}
                </p>
                <p className="art:mt-1 art:text-xs art:text-muted-foreground">
                  {clock ? clock.date : "Local time"}
                </p>
              </div>
            </div>
            <div>
              <p className="art:mb-2 art:text-xs art:text-muted-foreground art:@min-[640px]/artemis:text-right">
                {copy.clock.caption}
              </p>
              <time className="art:flex art:items-baseline art:font-mono art:text-5xl art:font-normal art:tracking-tight art:tabular-nums art:@min-[640px]/artemis:text-6xl" dateTime={clock ? clock.iso : undefined}>
                {clock ? clock.hours : "--"}
                <span className="art:px-1 art:text-muted-foreground">
                  {":"}
                </span>
                {clock ? clock.minutes : "--"}
                <span className="art:ml-3 art:text-2xl art:text-muted-foreground">
                  {clock ? clock.seconds : "--"}
                </span>
              </time>
            </div>
          </div>
          <div className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-x-6 art:gap-y-2 art:pt-5 art:text-xs art:text-muted-foreground">
            <p>
              {copy.legal}
            </p>
            <nav aria-label="Legal" className="art:flex art:gap-5">
              {copy.legalLinks.map((link, index) => <a key={index} href={link.href} {...newTab(link.href)} className="art:inline-flex art:min-h-10 art:items-center art:gap-1.5 art:rounded-full art:text-muted-foreground art:transition-colors art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:text-xs">
                {link.label}
              </a>)}
            </nav>
          </div>
        </div>
      </footer>
    </>);
}
